    public static string? PathData(DisplayProvider provider) => provider switch
    {
        DisplayProvider.Claude => ClaudePath,
        DisplayProvider.Codex => OpenAiPath,
        DisplayProvider.Grok => GrokPath,
        DisplayProvider.Cursor => CursorPath,
        DisplayProvider.Antigravity => AntigravityPath,
        _ => null,
    };

    /// Dedicated vector brand brush: Antigravity returns Google's official 4-color
    /// gradient (Blue -> Green -> Yellow -> Red), while other providers use their
    /// branded solid accent color.
    public static Brush BrandBrush(DisplayProvider provider, double opacity = 1.0)
    {
        if (provider == DisplayProvider.Antigravity)
        {
            // Official Antigravity gradient: dominant Google Blue body (#2C8BEC / #388BF2)
            // with warm amber-gold (#E28E30) and coral-red (#ED563F) crown.
            var brush = new LinearGradientBrush
            {
                StartPoint = new Point(0.35, 1.0),
                EndPoint = new Point(0.65, 0.0),
                Opacity = opacity,
            };
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(0x2C, 0x8B, 0xEC), 0.00)); // Deep Google Blue
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(0x38, 0x8B, 0xF2), 0.50)); // Vibrant Blue
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(0x42, 0xA8, 0xC6), 0.70)); // Subtle Cyan transition
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(0xE2, 0x8E, 0x30), 0.86)); // Warm Amber Gold
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(0xED, 0x56, 0x3F), 1.00)); // Coral Red crown
            brush.Freeze();
            return brush;
        }

        var color = ProviderIdentity.Accent(provider);
        return IslandColors.Brush(IslandColors.Alpha(color, opacity));
    }
}
